    "timeEstimateSeconds": 120,
    "caseStudy": "mountkirk_games",
    "caseStudySection": "Technical Constraints: Low Latency Matchmaking",
    "title": "Mountkirk Games: Scalable Matchmaking with Open Match and Private Service Connect",
    "scenario": "Mountkirk Games is implementing Open Match on Google Kubernetes Engine to match players based on skill rating (MMR), latency ping, and party size. Matchmaking tickets must be processed within 200ms. The matchmaking frontend microservice runs in a public GKE cluster, while the backend Director and Match Function services run in a private Shared VPC. How should you design the network connectivity and matchmaking architecture?",
    "keywords": [
      "Mountkirk Games",
      "Open Match",
      "GKE",
      "Private Service Connect",
      "Internal Load Balancing"
    ],
    "isMultiSelect": false,
    "expectedSelectCount": 1,
    "options": [
      {
        "letter": "A",
        "text": "Expose the backend Match Function on a public IP address with HTTP Basic Auth.",
        "isTrap": true,
        "trapType": "public_ip_security_risk"
      },
      {
        "letter": "B",
        "text": "Establish an IPsec VPN tunnel between pods in the same Google Cloud region.",
        "isTrap": true,
        "trapType": "premature_optimization"
      },
      {
        "letter": "C",
        "text": "Store match tickets in a Cloud Storage bucket and have match workers poll every 500ms.",
        "isTrap": true,
        "trapType": "wrong_storage_class_penalty"
      },
      {
        "letter": "D",
        "text": "Deploy Open Match core components in GKE using Private Service Connect (PSC) or Internal Application Load Balancers, keeping Match Functions private and using gRPC with keepalive connections.",
        "isTrap": false
      }
    ],
    "correct": "D",
    "explanation": "Open Match uses gRPC APIs between the Frontend, Backend, and Match Functions. Deploying these services behind Internal Load Balancers or Private Service Connect endpoints maintains strict zero-trust private networking without public exposure while keeping pings sub-millisecond.",
    "distractors": {
      "A": "Exposing backend matchmaking infrastructure to public IPs creates critical DDoS vulnerabilities.",
      "B": "VPN tunnels between pods in the same VPC add unnecessary CPU encryption overhead and latency.",
      "C": "Polling GCS for ephemeral matchmaking tickets creates extreme latency and rate limits.",
      "D": "Correct. Private Service Connect / Internal ALBs provide private, low-latency gRPC matchmaking transport."
    },
    "architectureComponents": [
      "Google Kubernetes Engine",
      "Open Match",
      "Private Service Connect",
      "Internal Load Balancer"
    ],
    "terraformSnippet": "resource \"google_compute_forwarding_rule\" \"open_match_ilb\" {\n  name                  = \"open-match-ilb\"\n  load_balancing_scheme = \"INTERNAL\"\n  backend_service       = google_compute_region_backend_service.match_function.id\n  ip_protocol           = \"TCP\"\n}",
    "officialDocUrl": "https://open-match.dev/site/docs/",
    "blockId": "BLOCK-1"
