    "terraformSnippet": "resource \"google_filestore_instance\" \"nfs_store\" {\n  name     = \"gke-shared-nfs\"\n  location = \"us-central1\"\n  tier     = \"ENTERPRISE\"\n  file_shares {\n    capacity_gb = 1024\n    name        = \"share1\"\n  }\n  networks {\n    network = google_compute_network.vpc.name\n    modes   = [\"MODE_IPV4\"]\n  }\n}",
