    "timeEstimateSeconds": 120,
    "caseStudy": "none",
    "title": "Zero-Downtime Perimeter Rollout with VPC-SC Dry-Run Mode",
    "scenario": "An enterprise is planning to apply a VPC Service Controls perimeter around 50 active production projects supporting thousands of microservices. The architecture team wants to identify all existing cross-project API calls, external service dependencies, and potential perimeter violation errors without actually blocking any production traffic during testing. What feature should be used?",
    "keywords": [
      "VPC Service Controls",
      "Dry-Run Mode",
      "Audit Logging",
      "Violation Analysis",
      "Zero Disruption"
    ],
    "isMultiSelect": false,
    "expectedSelectCount": 1,
    "options": [
      {
        "letter": "A",
        "text": "Ask every developer to list all API calls they made in the last 5 years in a word document.",
        "isTrap": true,
        "trapType": "manual_scripting_overhead"
      },
      {
        "letter": "B",
        "text": "Enforce the perimeter immediately on production and see what breaks.",
        "isTrap": true,
        "trapType": "single_point_of_failure"
      },
      {
        "letter": "C",
        "text": "Deploy the Service Perimeter in Dry-Run Mode (specifying spec {} dry-run configuration), analyze dry-run violation logs in Cloud Logging (vpcServiceControlsUniqueId), adjust perimeter rules, and promote to enforced mode once all legitimate traffic is permitted.",
        "isTrap": false
      },
      {
        "letter": "D",
        "text": "Disable all logging to save storage costs.",
        "isTrap": true,
        "trapType": "wrong_storage_class_penalty"
      }
    ],
    "correct": "C",
    "explanation": "VPC Service Controls Dry-Run Mode evaluates security policies and logs violations in Cloud Audit Logs without blocking requests. This allows teams to identify dependencies and refine ingress/egress rules before enforcing perimeters in production.",
    "distractors": {
      "A": "Manual developer surveys are incomplete, inaccurate, and cannot uncover automated system-to-system dependencies.",
      "B": "Immediate enforcement on production causes catastrophic microservice outages and business downtime.",
      "C": "Correct. Dry-Run Mode logs potential violations in Cloud Logging, enabling safe, empirical perimeter configuration.",
      "D": "Disabling logging prevents violation detection and blinds security operations."
    },
    "architectureComponents": [
      "VPC Service Controls",
      "Dry-Run Mode",
      "Cloud Logging",
      "Audit Logs"
    ],
    "terraformSnippet": "resource \"google_access_context_manager_service_perimeter\" \"dry_run_perimeter\" {\n  parent         = \"accessPolicies/123456789\"\n  name           = \"accessPolicies/123456789/servicePerimeters/dry_run_perimeter\"\n  title          = \"Dry Run Production Perimeter\"\n  use_explicit_dry_run_spec = true\n  spec {\n    restricted_services = [\"bigquery.googleapis.com\", \"storage.googleapis.com\"]\n    resources           = [\"projects/123456789012\"]\n  }\n}",
