    "terraformSnippet": "resource \"google_compute_disk\" \"csek_disk\" {\n  name = \"csek-protected-disk\"\n  zone = \"us-central1-a\"\n  disk_encryption_key {\n    raw_key = \"SGVsbG8gRnJvbSBHb29nbGUgQ2xvdWQgQ1NFSyE=\" # 256-bit base64\n  }\n}",
