    "architectureComponents": [
      "Confidential VMs",
      "AMD SEV",
      "Compute Engine",
      "Hardware Memory Encryption"
    ],
    "terraformSnippet": "resource \"google_compute_instance\" \"confidential_vm\" {\n  name         = \"fraud-detector-confidential\"\n  machine_type = \"n2d-standard-8\"\n  zone         = \"us-central1-a\"\n  confidential_instance_config {\n    enable_confidential_compute = true\n  }\n}",
    "officialDocUrl": "https://cloud.google.com/confidential-computing/confidential-vm/docs/about-cvm",
