    "options": [
      {
        "letter": "A",
        "text": "Use Ubuntu 12.04 with unverified custom kernels.",
        "isTrap": true,
        "trapType": "manual_scripting_overhead"
      },
      {
        "letter": "B",
        "text": "Enable Shielded GKE Nodes with Secure Boot (cryptographically verifies bootloader digital signatures) and Virtual Trusted Platform Module (vTPM) with Integrity Monitoring enabled.",
        "isTrap": false
      },
      {
        "letter": "C",
        "text": "Reboot nodes every 5 minutes.",
        "isTrap": true,
        "trapType": "single_point_of_failure"
      },
      {
        "letter": "D",
        "text": "Disable all firewall rules on the cluster.",
        "isTrap": true,
        "trapType": "public_ip_security_risk"
      }
    ],
    "correct": "B",
    "explanation": "Shielded GKE Nodes leverage Secure Boot (ensuring only signed kernel software runs), vTPM (measured boot), and Integrity Monitoring to detect and prevent boot-level and kernel-level rootkit tampering.",
    "distractors": {
      "A": "Unverified custom kernels bypass Secure Boot and violate enterprise security standards.",
      "B": "Correct. Shielded GKE Nodes with Secure Boot and vTPM integrity monitoring provides hardware-rooted node hardening.",
      "C": "Rebooting every 5 minutes causes severe application downtime without preventing rootkit persistence.",
      "D": "Disabling firewalls creates severe network vulnerabilities."
    },
    "architectureComponents": [
      "Shielded GKE Nodes",
      "Secure Boot",
      "vTPM",
      "Integrity Monitoring"
    ],
    "terraformSnippet": "resource \"google_container_node_pool\" \"hardened_pool\" {\n  name       = \"hardened-node-pool\"\n  cluster    = google_container_cluster.primary.name\n  node_config {\n    shielded_instance_config {\n      enable_secure_boot          = true\n      enable_integrity_monitoring = true\n    }\n  }\n}",
    "officialDocUrl": "https://cloud.google.com/kubernetes-engine/docs/how-to/shielded-gke-nodes",
    "blockId": "BLOCK-2",
