    "caseStudy": "none",
    "title": "Leveraging BigQuery Automated Long-Term Storage Price Reductions",
    "scenario": "An enterprise retains 10PB of historical regulatory audit logs in BigQuery. The compliance team rarely queries tables older than 90 days. The FinOps manager asks how much BigQuery storage pricing drops once a table or partition has not been modified for 90 consecutive days, and what action is required to trigger the discount. What is the correct answer?",
    "keywords": [
      "BigQuery",
      "Long-Term Storage",
      "50% Price Reduction",
      "90 Consecutive Days",
      "Automated Discount"
    ],
    "isMultiSelect": false,
    "expectedSelectCount": 1,
    "options": [
      {
        "letter": "A",
        "text": "You must manually export the table to Cloud Storage Coldline.",
        "isTrap": true,
        "trapType": "manual_scripting_overhead"
      },
      {
        "letter": "B",
        "text": "BigQuery does not offer long-term storage discounts.",
        "isTrap": true,
        "trapType": "wrong_storage_class_penalty"
      },
      {
        "letter": "C",
        "text": "Querying long-term storage takes 48 hours to return results.",
        "isTrap": true,
        "trapType": "premature_optimization"
      },
      {
        "letter": "D",
        "text": "BigQuery automatically lowers storage pricing by 50% (from $0.02/GB to $0.01/GB logical) for any table or partition not modified for 90 consecutive days, with zero manual action required and zero impact on query performance or availability.",
        "isTrap": false
      }
    ],
    "correct": "D",
    "explanation": "BigQuery automatically transitions tables or table partitions to Long-Term Storage if they are unedited for 90 consecutive days, reducing the storage price by 50% with zero degradation in query speed or availability.",
    "distractors": {
      "A": "Exporting to GCS Coldline makes data unavailable for instant SQL queries and incurs export compute costs.",
      "B": "BigQuery has included built-in automated long-term storage pricing since 2016.",
      "C": "Long-term storage queries execute with full performance and zero latency penalty.",
      "D": "Correct. BigQuery automatically grants a 50% price drop after 90 days of no modifications."
    },
    "architectureComponents": [
      "BigQuery",
      "Long-Term Storage Pricing",
      "Table Partitioning",
      "FinOps"
    ],
    "terraformSnippet": "resource \"google_bigquery_table\" \"regulatory_logs\" {\n  dataset_id = \"compliance_prod\"\n  table_id   = \"historical_audit_records\"\n  time_partitioning {\n    type = \"DAY\"\n  }\n}",
    "officialDocUrl": "https://cloud.google.com/bigquery/pricing#storage",
    "blockId": "BLOCK-2",
