    "keywords": [
      "Regional Persistent Disk",
      "repd",
      "Force Attach",
      "--force-attach",
      "Zonal Outage Recovery"
    ],
    "isMultiSelect": false,
    "expectedSelectCount": 1,
    "options": [
      {
        "letter": "A",
        "text": "Delete the regional disk.",
        "isTrap": true,
        "trapType": "single_point_of_failure"
      },
      {
        "letter": "B",
        "text": "Attach the Regional Persistent Disk to the standby VM using the '--force-attach' flag (or force_attach API parameter), which forcefully detaches the disk from the unreachable dead VM in zone A and attaches it to the healthy standby VM in zone B within seconds.",
        "isTrap": false
      },
      {
        "letter": "C",
        "text": "Wait 48 hours for zone us-central1-a to come back online.",
        "isTrap": true,
        "trapType": "single_point_of_failure"
      },
      {
        "letter": "D",
        "text": "Create a new blank empty disk and start with no data.",
        "isTrap": true,
        "trapType": "wrong_storage_class_penalty"
      }
    ],
    "correct": "B",
    "explanation": "Compute Engine supports force-attaching a Regional Persistent Disk to a new instance in the secondary replica zone. This breaks the stale lock from the dead VM and attaches the synchronously replicated disk to the failover VM instantly.",
    "distractors": {
      "A": "Deleting the disk destroys all database data.",
      "B": "Correct. Force-attaching repd breaks stale attachments and recovers stateful VMs in the secondary zone.",
      "C": "Waiting 48 hours violates recovery time objectives (RTO).",
      "D": "Using a blank disk causes 100% data loss."
    },
    "architectureComponents": [
      "Compute Engine",
      "Regional Persistent Disk (repd)",
      "Force-Attach API",
      "Disaster Recovery"
    ],
    "terraformSnippet": "resource \"google_compute_attached_disk\" \"failover_attach\" {\n  disk     = google_compute_region_disk.repd.id\n  instance = google_compute_instance.standby_vm.id\n  mode     = \"READ_WRITE\"\n}",
    "officialDocUrl": "https://cloud.google.com/compute/docs/disks/regional-persistent-disk#force_attaching_a_regional_disk",
