    "architectureComponents": [
      "Cloud Storage",
      "Signed URLs",
      "Cloud Spanner",
      "Cloud Monitoring",
      "Pub/Sub"
    ],
    "terraformSnippet": "resource \"google_storage_bucket_iam_member\" \"ota_reader\" {\n  bucket = google_storage_bucket.firmware.name\n  role   = \"roles/storage.objectViewer\"\n  member = \"serviceAccount:ota-service@terramearth-prod.iam.gserviceaccount.com\"\n}",
    "officialDocUrl": "https://cloud.google.com/storage/docs/access-control/signed-urls",
    "blockId": "BLOCK-3"
