    "timeEstimateSeconds": 120,
    "caseStudy": "terramearth",
    "caseStudySection": "Compliance and Privacy: Driver Telematics",
    "title": "TerramEarth: De-Identifying Driver GPS and Operator Identities with Cloud DLP",
    "scenario": "TerramEarth captures vehicle operator names, employee IDs, and high-precision GPS coordinates alongside mechanical sensor data. To comply with global privacy regulations, data shared with third-party researchers must have operator identities cryptographically pseudonymized (deterministic hashing with a salt) and GPS coordinates coarsened to a 5-kilometer grid. What service provides this transformation?",
    "keywords": [
      "TerramEarth",
      "Sensitive Data Protection",
      "Cloud DLP",
      "Pseudonymization",
      "Crypto-Hash",
      "K-Anonymity"
    ],
    "isMultiSelect": false,
    "expectedSelectCount": 1,
    "options": [
      {
        "letter": "A",
        "text": "Ask researchers to sign a promise that they will not look at operator names.",
        "isTrap": true,
        "trapType": "public_ip_security_risk"
      },
      {
        "letter": "B",
        "text": "Write custom regular expressions in a spreadsheet before sending to researchers.",
        "isTrap": true,
        "trapType": "manual_scripting_overhead"
      },
      {
        "letter": "C",
        "text": "Delete all GPS data from the database entirely.",
        "isTrap": true,
        "trapType": "wrong_storage_class_penalty"
      },
      {
        "letter": "D",
        "text": "Use Sensitive Data Protection (Cloud DLP) in the Dataflow pipeline to execute CryptoHashConfig tokenization on operator IDs and bucketing/generalization transformations on GPS coordinates.",
        "isTrap": false
      }
    ],
    "correct": "D",
    "explanation": "Google Cloud Sensitive Data Protection (formerly Cloud DLP) offers native de-identification transformations including cryptographic hashing (pseudonymization), date shifting, and geographic coordinate bucketing/generalization.",
    "distractors": {
      "A": "Legal agreements without technical data protection fail mandatory privacy compliance audits.",
      "B": "Manual regex in spreadsheets is impossible at multi-petabyte scale and highly error-prone.",
      "C": "Deleting all GPS data breaks agricultural spatial mapping and yield analytics.",
      "D": "Correct. Cloud DLP native de-identification rules provide automated, mathematically sound pseudonymization."
    },
    "architectureComponents": [
      "Sensitive Data Protection (Cloud DLP)",
      "Cloud Dataflow",
      "Cloud KMS"
    ],
    "terraformSnippet": "resource \"google_data_loss_prevention_deidentify_template\" \"operator_deid\" {\n  parent       = \"projects/terramearth-prod/locations/global\"\n  display_name = \"De-identify Operator PII\"\n  deidentify_config {\n    info_type_transformations {\n      transformations {\n        info_types { name = \"PERSON_NAME\" }\n        primitive_transformation {\n          crypto_hash_config {\n            crypto_key {\n              kms_wrapped {\n                wrapped_key    = \"dGVzdF9rZXk=\"\n                crypto_key_name = google_kms_crypto_key.dlp_key.id\n              }\n            }\n          }\n        }\n      }\n    }\n  }\n}",
    "officialDocUrl": "https://cloud.google.com/sensitive-data-protection/docs/deidentification-overview",
