    "terraformSnippet": "resource \"google_organization_policy\" \"deny_external_ips\" {\n  org_id     = \"123456789\"\n  constraint = \"constraints/compute.vmExternalIpAccess\"\n  list_policy {\n    deny {\n      all = true\n    }\n  }\n}",
