    "terraformSnippet": "resource \"google_access_context_manager_access_level\" \"corporate_devices\" {\n  parent = \"accessPolicies/123456789\"\n  name   = \"accessPolicies/123456789/accessLevels/corp_encrypted_devices\"\n  title  = \"Corporate Encrypted Devices\"\n  basic {\n    conditions {\n      device_policy {\n        require_screenlock          = true\n        require_admin_approval      = true\n        os_constraints {\n          os_type = \"DESKTOP_MAC\"\n        }\n      }\n    }\n  }\n}",
