    "bloomsLevel": "analyze",
    "timeEstimateSeconds": 120,
    "caseStudy": "none",
    "title": "Accelerating Executive Dashboards and Reducing BigQuery Costs with BI Engine",
    "scenario": "500 executives and sales managers load Looker Studio dashboards every morning. Each dashboard load executes 20 heavy SQL aggregation queries directly on BigQuery under on-demand pricing, causing high query bills ($10,000/month) and 10-second dashboard loading latency. How can the data architect achieve sub-second dashboard loading while drastically cutting query scan costs?",
    "keywords": [
      "BigQuery BI Engine",
      "In-Memory Acceleration",
      "Looker Studio Caching",
      "Sub-Second Dashboards",
      "Cost Reduction"
    ],
    "isMultiSelect": false,
    "expectedSelectCount": 1,
    "options": [
      {
        "letter": "A",
        "text": "Export tables to static PDF files emailed daily.",
        "isTrap": true,
        "trapType": "manual_scripting_overhead"
      },
      {
        "letter": "B",
        "text": "Disable Looker Studio.",
        "isTrap": true,
        "trapType": "single_point_of_failure"
      },
      {
        "letter": "C",
        "text": "Provision BigQuery BI Engine reservation capacity (in-memory acceleration) in the analytical project, which caches frequently queried dashboard tables in fast in-memory memory, delivering sub-second query responses and eliminating on-demand query scan costs for cached queries.",
        "isTrap": false
      },
      {
        "letter": "D",
        "text": "Ask executives to only check dashboards once a year.",
        "isTrap": true,
        "trapType": "manual_scripting_overhead"
      }
    ],
    "correct": "C",
    "explanation": "BigQuery BI Engine is a built-in in-memory analysis service. Provisioning BI Engine capacity automatically caches frequently queried datasets in RAM, delivering sub-second dashboard render speeds in Looker Studio while eliminating on-demand per-query scan charges for cached data.",
    "distractors": {
      "A": "Static PDFs lack interactivity, filtering, and real-time drill-down capabilities.",
      "B": "Disabling Looker Studio eliminates executive reporting.",
      "C": "Correct. BigQuery BI Engine in-memory acceleration provides sub-second dashboards and eliminates on-demand query scan charges.",
      "D": "Restricting executive dashboard usage destroys business operational visibility."
    },
    "architectureComponents": [
      "BigQuery BI Engine",
      "Looker Studio",
      "In-Memory Acceleration",
      "FinOps"
    ],
    "terraformSnippet": "resource \"google_bigquery_bi_reservation\" \"dashboard_cache\" {\n  location = \"US\"\n  size     = 10737418240 # 10 GB in-memory BI Engine cache\n}",
    "officialDocUrl": "https://cloud.google.com/bigquery/docs/bi-engine-overview",
