    "keywords": [
      "Canary Analysis",
      "Kayenta",
      "Statistical Verification",
      "Cloud Deploy",
      "Cloud Monitoring SLIs"
    ],
    "isMultiSelect": false,
    "expectedSelectCount": 1,
    "options": [
      {
        "letter": "A",
        "text": "Have a developer look at a graph for 10 seconds and click 'Approve'.",
        "isTrap": true,
        "trapType": "manual_scripting_overhead"
      },
      {
        "letter": "B",
        "text": "Deploy directly to 100% production without testing.",
        "isTrap": true,
        "trapType": "single_point_of_failure"
      },
      {
        "letter": "C",
        "text": "Integrate Automated Canary Analysis (e.g. Kayenta / Cloud Deploy automated verification hooks) with Cloud Monitoring, executing automated statistical metric comparisons between baseline and canary pods over a 30-minute evaluation window to trigger automated promotion or rollback.",
        "isTrap": false
      },
      {
        "letter": "D",
        "text": "Roll back all deployments automatically regardless of success.",
        "isTrap": true,
        "trapType": "single_point_of_failure"
      }
    ],
    "correct": "C",
    "explanation": "Automated Canary Analysis (ACA) uses statistical algorithms (such as Kayenta / Cloud Deploy verification jobs) to compare real-time telemetry between baseline and canary instances, objectively determining if a release is healthy without human error.",
    "distractors": {
      "A": "Manual eyeball checks miss subtle 2% latency regressions and edge-case error spikes.",
      "B": "Direct 100% deployments maximize outage blast radius.",
      "C": "Correct. Automated Canary Analysis provides objective, statistical metric verification for safe continuous delivery.",
      "D": "Rolling back everything prevents new features and bug fixes from ever reaching production."
    },
    "architectureComponents": [
      "Cloud Deploy",
      "Automated Canary Analysis",
      "Cloud Monitoring",
      "GKE Gateway API"
    ],
