    "terraformSnippet": "resource \"google_cloud_run_v2_service\" \"multi_container_app\" {\n  name     = \"app-with-sidecar\"\n  location = \"us-central1\"\n  template {\n    containers {\n      name  = \"web-app\"\n      image = \"us-docker.pkg.dev/my-project/app/web:v1\"\n      ports {\n        container_port = 8080\n      }\n    }\n    containers {\n      name  = \"otel-collector\"\n      image = \"us-docker.pkg.dev/my-project/monitoring/otel:v1\"\n    }\n  }\n}",
