    "terraformSnippet": "resource \"google_pubsub_subscription\" \"lab_results_sub\" {\n  name                   = \"lab-results-ordered-sub\"\n  topic                  = google_pubsub_topic.lab_results.name\n  enable_message_ordering = true\n}",
