    "timeEstimateSeconds": 120,
    "caseStudy": "none",
    "title": "Comparing Disaster Recovery Patterns: Active-Active (Hot-Hot) vs Warm Standby",
    "scenario": "An enterprise architect is evaluating DR strategies for a Tier-1 financial platform requiring RTO < 5 seconds and RPO = 0 vs a Tier-2 internal HR application requiring RTO < 2 hours and RPO < 1 hour. What disaster recovery architectures meet these respective business tiers cost-effectively?",
    "keywords": [
      "Disaster Recovery",
      "Active-Active",
      "Warm Standby",
      "RTO / RPO",
      "Spanner vs Cloud SQL"
    ],
    "isMultiSelect": false,
    "expectedSelectCount": 1,
    "options": [
      {
        "letter": "A",
        "text": "Do not implement any disaster recovery strategy.",
        "isTrap": true,
        "trapType": "single_point_of_failure"
      },
      {
        "letter": "B",
        "text": "For Tier-1: Deploy Active-Active (Hot-Hot) multi-region compute behind a Global Load Balancer with Cloud Spanner multi-region (RTO < 5s, RPO 0). For Tier-2: Deploy Warm Standby / Backup & Restore using Cloud SQL with cross-region read replicas promoted on-demand (RTO < 2h, RPO < 1h), optimizing costs.",
        "isTrap": false
      },
      {
        "letter": "C",
        "text": "Deploy Active-Active multi-region Cloud Spanner for all Tier-1 and Tier-2 applications.",
        "isTrap": true,
        "trapType": "wrong_storage_class_penalty"
      },
      {
        "letter": "D",
        "text": "Use paper backups for both tiers.",
        "isTrap": true,
        "trapType": "manual_scripting_overhead"
      }
    ],
    "correct": "B",
    "explanation": "Tiered DR alignment matches technical architecture to business recovery objectives. Tier-1 requires Hot-Hot multi-region with Cloud Spanner for instant zero-loss failover. Tier-2 uses Warm Standby with Cloud SQL cross-region replicas to achieve 2-hour RTO at a fraction of the infrastructure cost.",
    "distractors": {
      "A": "Zero DR leaves critical business platforms vulnerable to catastrophic regional outages.",
      "B": "Correct. Aligning Tier-1 to Hot-Hot Active-Active and Tier-2 to Warm Standby balances business SLAs with FinOps costs.",
      "C": "Deploying multi-region Spanner for low-criticality Tier-2 HR apps wastes budget on over-engineered infrastructure.",
      "D": "Paper backups cannot meet digital enterprise recovery objectives."
    },
    "architectureComponents": [
      "Disaster Recovery Topologies",
      "Cloud Spanner Multi-Region",
      "Cloud SQL Cross-Region Replicas",
      "Global Load Balancing"
    ],
    "terraformSnippet": "resource \"google_sql_database_instance\" \"dr_replica\" {\n  name                 = \"hr-db-dr-replica\"\n  region               = \"us-east1\"\n  master_instance_name = google_sql_database_instance.primary_db.name\n  instance_type        = \"READ_REPLICA_INSTANCE\"\n  settings {\n    tier = \"db-custom-2-7680\"\n  }\n}",
    "officialDocUrl": "https://cloud.google.com/architecture/disaster-recovery-scenarios-for-data",
    "blockId": "BLOCK-5",
