    "terraformSnippet": "resource \"google_spanner_database\" \"pitr_db\" {\n  instance                 = google_spanner_instance.primary.name\n  name                     = \"finance_master\"\n  version_retention_period = \"7d\" # 7 days PITR\n}",
    "officialDocUrl": "https://cloud.google.com/spanner/docs/pitr",
