    "timeEstimateSeconds": 120,
    "caseStudy": "none",
    "title": "Evaluating RTO and RPO Trade-Offs Across Disaster Recovery Strategies",
    "scenario": "An enterprise disaster recovery board is establishing Recovery Time Objective (RTO) and Recovery Point Objective (RPO) targets for corporate applications. Which of the following correctly matches the Google Cloud disaster recovery strategy with its expected RTO and RPO profile?",
    "keywords": [
      "Disaster Recovery",
      "RTO",
      "RPO",
      "Hot Standby",
      "Warm Standby",
      "Cold Standby",
      "Backup & Restore"
    ],
    "isMultiSelect": false,
    "expectedSelectCount": 1,
    "options": [
      {
        "letter": "A",
        "text": "Active-Active (Hot-Hot) Multi-Region: RTO near 0, RPO = 0 (highest cost); Warm Standby: RTO in minutes/hours, RPO in minutes (moderate cost); Cold Standby / Backup & Restore: RTO in hours/days, RPO in hours (lowest cost).",
        "isTrap": false
      },
      {
        "letter": "B",
        "text": "Backup & Restore provides RTO < 1 second and RPO = 0 at zero cost.",
        "isTrap": true,
        "trapType": "wrong_storage_class_penalty"
      },
      {
        "letter": "C",
        "text": "Cold Standby has lower RTO than Active-Active.",
        "isTrap": true,
        "trapType": "premature_optimization"
      },
      {
        "letter": "D",
        "text": "RTO and RPO are identical metrics with no difference.",
        "isTrap": true,
        "trapType": "manual_scripting_overhead"
      }
    ],
    "correct": "A",
    "explanation": "In DR architecture: Active-Active (Hot-Hot) delivers sub-second RTO and RPO 0 at highest cost; Warm Standby delivers minutes-to-hours RTO/RPO with scaled-down standby resources; Backup & Restore delivers lowest cost but has hours-to-days RTO and hours RPO.",
    "distractors": {
      "A": "Correct. Accurate classification of Active-Active (Hot-Hot), Warm Standby, and Backup & Restore RTO/RPO/Cost trade-offs.",
      "B": "Backup & Restore requires full database and VM recreation, taking hours-to-days (not sub-second).",
      "C": "Cold standby requires manual spinning up of all resources, taking much longer than Active-Active.",
      "D": "RTO (Recovery Time Objective = how fast you recover) and RPO (Recovery Point Objective = allowable data loss) are distinct metrics."
    },
    "architectureComponents": [
      "Disaster Recovery Strategies",
      "RTO / RPO Matrix",
      "Active-Active",
      "Warm Standby",
      "Backup and Restore"
    ],
    "terraformSnippet": "resource \"google_compute_resource_policy\" \"dr_snapshot\" {\n  name   = \"daily-dr-snapshot-policy\"\n  region = \"us-central1\"\n  snapshot_schedule_policy {\n    schedule {\n      daily_schedule {\n        days_in_cycle = 1\n        start_time    = \"04:00\"\n      }\n    }\n  }\n}",
    "officialDocUrl": "https://cloud.google.com/architecture/disaster-recovery-scenarios-for-data#choosing_a_dr_pattern",
