    "terraformSnippet": "resource \"google_dataflow_job\" \"telemetry_sync\" {\n  name              = \"hrl-video-telemetry-sync\"\n  template_gcs_path = \"gs://hrl-dataflow-templates/sync_pipeline\"\n  temp_gcs_location = \"gs://hrl-temp/dataflow\"\n}",
    "officialDocUrl": "https://beam.apache.org/documentation/patterns/grouping-data/",
