    "terraformSnippet": "resource \"google_storage_bucket\" \"video_vault\" {\n  name          = \"hrl-historical-broadcast-vault\"\n  location      = \"US\"\n  lifecycle_rule {\n    action {\n      type          = \"SetStorageClass\"\n      storage_class = \"ARCHIVE\"\n    }\n    condition {\n      age = 365\n    }\n  }\n}",
