    "architectureComponents": [
      "Storage Transfer Service",
      "Transfer Agent Pool",
      "Cloud Storage",
      "Dedicated Interconnect"
    ],
    "terraformSnippet": "resource \"google_storage_transfer_agent_pool\" \"nfs_pool\" {\n  name         = \"netapp-nfs-agent-pool\"\n  display_name = \"On-premises NetApp Transfer Pool\"\n}",
    "officialDocUrl": "https://cloud.google.com/storage-transfer/docs/on-prem-overview",
