    "terraformSnippet": "resource \"google_bigtable_app_profile\" \"terram_ingest_profile\" {\n  instance       = google_bigtable_instance.fleet_db.name\n  app_profile_id = \"tractor-telemetry-profile\"\n  multi_cluster_routing_use_any = true\n  ignore_warnings               = true\n}",
